def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a.

    A 400 number has exactly two distinct prime factors, each with an
    even exponent. The supported range is 36 <= a <= 10**12.

    Such numbers are precisely squares whose roots have exactly two
    distinct prime factors. In particular, the answer for 404 is 400.
    """
    root = isqrt(a)
    while root >= 6:
        remaining = root
        distinct = 0
        if remaining % 2 == 0:
            distinct += 1
            while remaining % 2 == 0:
                remaining //= 2
        divisor = 3
        while divisor * divisor <= remaining:
            if remaining % divisor == 0:
                distinct += 1
                while remaining % divisor == 0:
                    remaining //= divisor
                if distinct > 2:
                    break
            divisor += 2
        if remaining > 1:
            distinct += 1
        if distinct == 2:
            return root * root
        root -= 1
    return 36

