def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count ordered paths of K moves through distinct empty grid cells.

    Moves go up, down, left, or right. Every empty cell is a possible
    starting point, and a cell cannot appear twice in one path.
    H and W are at most 10 and K is at most 11.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == '.']
    if len(cells) <= K:
        return 0
    indices = {cell: i for i, cell in enumerate(cells)}
    adjacent = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                adjacent[i].append(j)

    visited = [False] * len(cells)

    def walk(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for neighbor in adjacent[cell]:
            if not visited[neighbor]:
                visited[neighbor] = True
                total += walk(neighbor, remaining - 1)
                visited[neighbor] = False
        return total

    total = 0
    for start in range(len(cells)):
        visited[start] = True
        total += walk(start, K)
        visited[start] = False
    return total

